<?php
declare(strict_types=1);
namespace App\Http\Controllers\Academic;
use App\Http\Controllers\Controller;use App\Http\Requests\Academic\SaveAttendanceRequest;use App\Models\{AcademicYear,Semester,StudentAttendance};use App\Services\Academic\{AcademicAccessService,AcademicEntryService};use Illuminate\Http\{RedirectResponse,Request};use Illuminate\View\View;
class AttendanceController extends Controller {public function index(Request $r,AcademicAccessService $access):View{$year=$r->integer('academic_year_id')?:AcademicYear::where('is_active',true)->value('id');$semester=$r->integer('semester_id')?:Semester::where('academic_year_id',$year)->where('is_active',true)->value('id');$date=$r->input('attendance_date',now()->toDateString());$roomId=$r->integer('classroom_id');$rooms=$access->classrooms($r->user())->where('academic_year_id',$year)->get();$room=$roomId?$access->ensureClassroom($r->user(),$roomId):null;$students=$room?->students()->orderBy('full_name')->get()??collect();$saved=StudentAttendance::where('classroom_id',$roomId)->whereDate('attendance_date',$date)->get()->keyBy('student_id');return view('academic.attendance.index',compact('year','semester','date','rooms','room','students','saved')+['years'=>AcademicYear::orderByDesc('starts_at')->get(),'semesters'=>Semester::where('academic_year_id',$year)->get()]);}public function store(SaveAttendanceRequest $r,AcademicEntryService $s):RedirectResponse{$s->saveAttendance($r);return back()->with('success','Absensi siswa berhasil disimpan.');}public function history(Request $r,AcademicAccessService $a):View{$rooms=$a->classrooms($r->user())->get();$q=StudentAttendance::with(['student','classroom.gradeLevel'])->latest('attendance_date');if($r->filled('classroom_id')){$a->ensureClassroom($r->user(),$r->integer('classroom_id'));$q->where('classroom_id',$r->integer('classroom_id'));}elseif($r->user()->hasRole('guru'))$q->whereIn('classroom_id',$rooms->pluck('id'));if($r->filled('attendance_date'))$q->whereDate('attendance_date',$r->date('attendance_date'));return view('academic.attendance.history',['rooms'=>$rooms,'records'=>$q->paginate(50)->withQueryString()]);}}
